import React, { useState } from 'react';
import { Layout, Avatar, Row, Col, Card, Typography, Input, Button, List, Spin } from 'antd';
import Chat from './components/Chat';
import Dashboard from './components/Dashboard';
import axios from 'axios';

const { Header, Content } = Layout;
const { Title, Text } = Typography;

function App() {
  const [showDashboard, setShowDashboard] = useState(false);
  const [dashboardData, setDashboardData] = useState(null);
  const [showChatFull, setShowChatFull] = useState(false);
  const [initialInput, setInitialInput] = useState('');
  const [noticiasRecentes, setNoticiasRecentes] = useState([]);
  const [loadingNoticias, setLoadingNoticias] = useState(true);

  React.useEffect(() => {
    // Busca as 10 notícias mais recentes ao carregar a tela inicial
    async function fetchNoticias() {
      setLoadingNoticias(true);
      try {
        const res = await axios.get('http://localhost:4000/api/status');
        // Não existe endpoint direto para as 10 mais recentes, então vamos buscar todas e pegar as 10 mais recentes por data
        // (Ideal: criar endpoint dedicado no backend futuramente)
        // Aqui, só temos as 3 primeiras no status, então vamos buscar todas via /api/noticias com termo vazio
        const allRes = await axios.post('http://localhost:4000/api/noticias', { termo: '' });
        const noticias = allRes.data;
        // Ordena por data decrescente
        noticias.sort((a, b) => (b.data > a.data ? 1 : b.data < a.data ? -1 : 0));
        setNoticiasRecentes(noticias.slice(0, 10));
      } catch (e) {
        setNoticiasRecentes([]);
      }
      setLoadingNoticias(false);
    }
    fetchNoticias();
  }, []);

  // Função para ser passada ao Chat e ativar o dashboard
  const handleShowDashboard = (data) => {
    setDashboardData(data);
    setShowDashboard(true);
    setShowChatFull(false);
  };

  // Quando o usuário envia o primeiro input, mostra o chat fullscreen
  const handleInitialInput = () => {
    setShowChatFull(true);
  };

  // Quando o dashboard é fechado, volta para o chat fullscreen
  const handleCloseDashboard = () => {
    setShowDashboard(false);
    setDashboardData(null);
    setShowChatFull(true);
  };

  return (
    <Layout style={{ minHeight: '100vh', background: '#fafbfc' }}>
      <Header style={{ background: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'space-between', boxShadow: '0 2px 8px #f0f1f2', position: 'fixed', width: '100%', zIndex: 10, top: 0, left: 0, height: 64}}>
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <img src="https://pages.cortex-intelligence.com/hs-fs/hubfs/Logo%20cortex%20principal.png?width=110&height=19&name=Logo%20cortex%20principal.png" alt="cortex logo" style={{ height: 22, marginRight: 12 }} />
        </div>
        <Avatar style={{ background: '#e6e6e6', color: '#888' }}>WM</Avatar>
      </Header>
      <Content style={{ display: 'flex', justifyContent: 'center', alignItems: 'flex-start', minHeight: '100vh', paddingTop: 64, background: '#fafbfc', transition: 'all 0.5s' }}>
        {showDashboard ? (
          <Row style={{ width: '100%', maxWidth: 1400, minHeight: 'calc(100vh - 64px)', transition: 'all 0.5s' }} gutter={32}>
            <Col span={16} style={{ height: 'calc(100vh - 64px)', display: 'flex', flexDirection: 'column', transition: 'all 0.5s' }}>
              <Dashboard data={dashboardData} />
            </Col>
            <Col span={8} style={{ height: 'calc(100vh - 64px)', display: 'flex', flexDirection: 'column', transition: 'all 0.5s' }}>
              <Chat onShowDashboard={handleShowDashboard} fullscreen={false} />
            </Col>
          </Row>
        ) : showChatFull ? (
          <div style={{ width: '100%', display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 'calc(100vh - 64px)', transition: 'all 0.5s' }}>
            <Chat onShowDashboard={handleShowDashboard} fullscreen={true} />
          </div>
        ) : (
          <div style={{ width: '100%', maxWidth: 700, margin: '0 auto', padding: '32px 0', display: 'flex', flexDirection: 'column', gap: 32 }}>
            <Card style={{ borderRadius: 16, marginBottom: 24, background: '#ede6fa', textAlign: 'center' }}>
              <Title level={2} style={{ marginBottom: 0, color: '#222', fontWeight: 700 }}>Bem-vindo(a) à sua plataforma de <span style={{ color: '#6c4ed9' }}>Comunicação Estratégica</span></Title>
              <Text style={{ fontSize: 18, color: '#444' }}>O que você quer monitorar?</Text>
              <div style={{ marginTop: 24, display: 'flex', justifyContent: 'center', alignItems: 'center', gap: 12 }}>
                <Input
                  size="large"
                  placeholder="Pode me dizer temas, assuntos ou empresas que gostaria de saber mais."
                  value={initialInput}
                  onChange={e => setInitialInput(e.target.value)}
                  onPressEnter={handleInitialInput}
                  style={{ maxWidth: 400, borderRadius: 24 }}
                  disabled={loadingNoticias}
                />
                <Button
                  type="primary"
                  size="large"
                  shape="circle"
                  icon={<span role="img" aria-label="enviar">✈️</span>}
                  onClick={handleInitialInput}
                  disabled={!initialInput || loadingNoticias}
                  style={{ background: '#6c4ed9', border: 'none' }}
                />
              </div>
            </Card>
            <Card style={{ borderRadius: 16, boxShadow: '0 2px 8px #ececff', minHeight: 300 }}>
              <Title level={4} style={{ marginBottom: 16 }}>Últimas notícias</Title>
              {loadingNoticias ? (
                <Spin />
              ) : (
                <List
                  itemLayout="vertical"
                  dataSource={noticiasRecentes}
                  renderItem={item => (
                    <List.Item key={item.id}>
                      <List.Item.Meta
                        title={<span style={{ color: '#6c4ed9', fontWeight: 500 }}>{item.titulo}</span>}
                        description={<span><b>Fonte:</b> {item.fonte} &nbsp; <b>Data:</b> {item.data} &nbsp; <b>Mídia:</b> {item.midia || 'N/A'}</span>}
                      />
                      <div style={{ color: '#444' }}>{item.descricao}</div>
                    </List.Item>
                  )}
                />
              )}
            </Card>
          </div>
        )}
      </Content>
    </Layout>
  );
}

export default App;
